head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.removeRows([0]);
};
scwin._isCountTr = function() {
    var el = WebSquare.wUnit.getJq('#gridView1_body_tbody tr').not('.w2grid_hidedRow');
    return el.length;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 jsonData 부분을 확인한다. (코멘트확인)
    //1. Check the jsonData part in the Script tab. (Comment confirmation)
    //Test step 2. scwin.trigger1_onclick 부분을 확인한다.
    //2. Check the scwin.trigger1_onclick section.
    //Verify 2. dataList1.removeRows([0]);
    //Test step 3. 브라우저에서 removeRows([0])버튼을 클릭한다.
    //3. Click the removeRows ([0]) button in your browser.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 첫번째 row 가 삭제된다. (삭제된 후 첫번 째 row 만 setCellReadOnly / setCellDisabled 가 적용되며, 두번 째 row는 setCellReadOnly / setCellDisabled 가 적용이 안되는 현상이 정상임.) 
    //3. The first row is deleted. (Only the first row after setCellReadOnly / setCellDisabled is applied, and the second row is not applicable to setCellReadOnly / setCellDisabled.)
    WebSquare.wUnit.addCommand("assert", "scwin._isCountTr() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getCellReadOnly(1, 'col3') == ''", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getCellDisabled(1, 'col4') == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a"
    }, {
        "col1": "b"
    }, {
        "col1": "c"
    }];
    dataList1.setJSON(jsonData);
    gridView1.setCellReadOnly(0, "col3", true);
    gridView1.setCellReadOnly(1, "col3", true);
    gridView1.setCellDisabled(0, "col4", true);
    gridView1.setCellDisabled(1, "col4", true);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
